func (h *Handler) ListSandboxCredentials(ctx context.Context, params serverapi.ListSandboxCredentialsParams) (serverapi.ListSandboxCredentialsRes, error) {
	principal, err := credentialBrokerPrincipal(ctx)
	if err != nil {
